function XUiMusicPlayerCDView:_OnCurPlayMusicChange(direction)
    self._CurCDShowMusicID = self._Control:GetCDPlayerControl():GetCurPlayingMusicID()
    self:_RefreshCDByMusicID(self._CurCDShowMusicID)

    local cdControl = self._Control:GetCDPlayerControl()
    local rawList = cdControl:GetCurRawMusicIdList()
    local totalCount = #rawList
    local target = (table.indexof(rawList, self._CurCDShowMusicID) or 1) - 1
    local rawCur = self._CDListTable.Imp.StartIndex
    local diff = 0
    if totalCount > 0 then
        local cur = rawCur % totalCount
        local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
        if direction == XMusicPlayerEnum.MusicSwitchDirection.Next then
            -- 正向: diff 始终为正,往前进
            diff = (target - cur) % totalCount
            if diff == 0 then diff = totalCount end
        elseif direction == XMusicPlayerEnum.MusicSwitchDirection.Prev then
            -- 反向: 算后退距离,用 rawCur - backwardDist 往回退
            local backwardDist = (cur - target) % totalCount
            if backwardDist == 0 then backwardDist = totalCount end
            diff = -backwardDist
        else
            -- Jump: 最短路径
            diff = (target - cur) % totalCount
            if diff > totalCount / 2 then
                diff = diff - totalCount
            end
        end
    end
    if self._CDListTable.Imp.MoveType == CS.XDynamicTableCurve.MovementType.Clamped then
        -- Clamped 模式不支持虚拟索引，直接定位到实际下标
        self._CDListTable:TweenToIndex(target)
    else
        self._CDListTable:TweenToIndex(rawCur + diff)
    end
end

---拖拽滑动切换CD: 按视图位置移动一格,能播则跳转播放,不能播则只滚动展示
---@param isNext boolean true=右滑下一首, false=左滑上一首
function XUiMusicPlayerCDView:OnCDSwipe(isNext)
    self._Control:DispatchEvent(XMVCA.XMusicPlayer.EventIds.EVENT_VIEW_PLAY_SFX, XMVCA.XMusicPlayer.Enum.AudioName.cdSFXSwitch)
    local cdControl = self._Control:GetCDPlayerControl()
    local rawList = cdControl:GetCurRawMusicIdList()
    local totalCount = #rawList
    if totalCount <= 0 then return end

    -- 用表格当前视觉位置算下一格,不用 CurCDShowMusicID
    local rawCur = self._CDListTable.Imp.StartIndex
    local cur = rawCur % totalCount
    local nextViewIdx
    if isNext then
        nextViewIdx = (cur + 1) % totalCount
    else
        nextViewIdx = (cur - 1 + totalCount) % totalCount
    end
    local nextIdx = nextViewIdx + 1  -- 0-based → 1-based

    local musicID = rawList[nextIdx]
    self._CurCDShowMusicID = musicID
    self:_RefreshCDByMusicID(musicID)

    local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
    local useStatus = cdControl:GetMusicUseStatusAndConditionDesc(musicID)
    -- Clamped 模式使用实际索引；Loop 模式使用虚拟索引以保持移动方向
    local targetIdx
    if self._CDListTable.Imp.MoveType == CS.XDynamicTableCurve.MovementType.Clamped then
        targetIdx = nextViewIdx
    else
        targetIdx = isNext and (rawCur + 1) or (rawCur - 1)
    end
    if useStatus ~= XMusicPlayerEnum.MusicUseStatus.unlock then
        if musicID == cdControl:GetCurPlayingMusicID() then
            -- 拖回当前正在播放的歌曲，不重复播，直接滚回去
            self._CDListTable:TweenToIndex(targetIdx)
        else
            -- 不同歌曲: 跳转播放(tween 由 _OnCurPlayMusicChange 驱动)
            cdControl:JumpPlayByMusicIDWithNotify(cdControl:GetCurMusicListType(), musicID)
        end
    else
        -- 不可播放: 只滚动到该CD展示
        self._CDListTable:TweenToIndex(targetIdx)
    end
end

