function XUiMusicPlayerCDView:_RefreshCDByMusicID(musicID)
    local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
    local cdControl = self._Control:GetCDPlayerControl()
    local musicListControl = self._Control:GetMusicmusicListControl()
    local co = self._Control:GetMusicPlayerconfigControl():GetMusicPlayerAlbumCOByid(musicID)

    local isInBGMList = musicListControl:CheckMusicIsInListByListType(XMusicPlayerEnum.MusicListType.BGM, musicID)
    local isInLickList = musicListControl:CheckMusicIsInListByListType(XMusicPlayerEnum.MusicListType.Favorite, musicID)
    XMVCA.XMusicPlayer.Util.SetBtnStatusPro(self.BtnBgmList, isInBGMList and CS.UiButtonState.Select or CS.UiButtonState.Normal)
    XMVCA.XMusicPlayer.Util.SetBtnStatusPro(self.BtnLikeList, isInLickList and CS.UiButtonState.Select or CS.UiButtonState.Normal)
    self.BtnImmerseMode:SetButtonState(CS.UiButtonState.Normal)

    self.TxtMusicName.text = co.Name
    self._MusicNameScrolling:Play()

    local composerBrief = co.ComposeBrief 
    if string.IsNilOrEmpty(composerBrief) then
        self.TxtComposer.text = XUiHelper.ConvertLineBreakSymbol(co.Composer) 
    else
        self.TxtComposer.text = XUiHelper.ConvertLineBreakSymbol(composerBrief)
    end
    self:_RefreshFullInfoBtn()

    self.GoEggTip.gameObject:SetActive(false)
    self.TxtEggTip.text = co.EggText
    if cdControl:NeedShowEggTag(musicID) then
        self.BtnEgg.gameObject:SetActive(true)
    else
        self.BtnEgg.gameObject:SetActive(false)
    end
end

---全量刷新CD列表(列表变更/初始化时调用)
function XUiMusicPlayerCDView:_RefreshCDList(musicID)
    local cdControl = self._Control:GetCDPlayerControl()
    local rawList = cdControl:GetCurRawMusicIdList()
    local count = #rawList
    -- 仅1首时走Clamped(不可循环滚动), 多首走Loop(无限循环)
    self._CDListTable.Imp.MoveType = count <= 2
            and CS.XDynamicTableCurve.MovementType.Clamped
            or CS.XDynamicTableCurve.MovementType.Loop
    self._CDListTable:SetDataSource(rawList)
    local index = table.indexof(rawList, musicID) or 1
    self._CDListTable:ReloadData(count > 0 and (index - 1) or -1)
end



function XUiMusicPlayerCDView:OnDynamicTableEvent(event, index, grid)
    if event == DYNAMIC_DELEGATE_EVENT.DYNAMIC_GRID_ATINDEX then
        local visualIndex = index
        index = index % self._CDListTable.Imp.TotalCount + 1
        grid:UpdateCDCellData(index, self, visualIndex)
    end
end


function XUiMusicPlayerCDView:_RefreshFullInfoBtn()
    local XMusicPlayerEnum = XMVCA.XMusicPlayer.Enum
    local co = self._Control:GetMusicPlayerconfigControl():GetMusicPlayerAlbumCOByid(self._CurCDShowMusicID)
    local hasBrief = co and not string.IsNilOrEmpty(co.ComposeBrief)

    local curUIStatus = self.Parent:GetMusicPlayerUIStatus()
    local isImmerse = curUIStatus == XMusicPlayerEnum.MusicMainUIStatus.immerse
        or curUIStatus == XMusicPlayerEnum.MusicMainUIStatus.immersePro

    self.BtnMusicFullInfo.gameObject:SetActive(hasBrief and not isImmerse)
end

